def read_static(path,libc):
    rows={}
    for domain,filename in (('main',path),('libc',libc)):
        with filename.open('rb') as stream:
            elf=ELFFile(stream)
            for off,size in CODE_RANGES[domain]:
                raw=previous.elf_bytes(elf,stream,off,size)
                rows[domain+':'+hex(off)]=dict(size=size,hex=raw.hex(),sha256=raw_hash(raw))
    assert {key:value['sha256'] for key,value in rows.items()}==CODE_SHA256
    return rows

def independent_controls(path,libc):
    rows=[]
    for base in controls.BASES:
        for label in controls.PROFILES+controls.FORMAT_PROFILES:
            compare=controls.compare_format if label in controls.FORMAT_PROFILES else controls.compare
            rows.append(compare(path,libc,base,label))
    negatives=controls.guards(path)
    assert rows==CONTROL_SPECS and negatives==ROLLBACK_SPECS
    return rows,negatives

PARENT_FIELDS=('instruction_observations','instruction_trace_sha256','observation_sites','observed_code','observed_code_sha256',
    'retained_u32_lookup','destructor_callback','native_reads','native_stores','free_calls','prior_objects_retention',
    'lookup_descriptor_integrity','observed_PLT_entries','next_VM_call')

class IdentifierSeedOpenScenario(previous.PostU32QueryDestructorScenario):
    def __init__(self,control):
        super().__init__(control)
        self._idopen_active=False;self._idopen_returned=False;self._idopen_done=False
        self._idopen_count=0;self._idopen_trace=[];self._idopen_code={}
        self._idopen_rows=[];self._idopen_writes=[];self._idopen_protected=[]

    def _postdtor_next(self,cpu,pc):
        super()._postdtor_next(cpu,pc)
        old=prior_evidence()['case_result']
        h=hashlib.sha256()
        for key in self._postdtor_trace:h.update(key.encode()+bytes.fromhex(self._postdtor_code[key]))
        values=(self._postdtor_count,h.hexdigest(),self._postdtor_trace,self._postdtor_code,previous.digest(self._postdtor_code),
            self._postdtor_parent,self._postdtor_call,self._postdtor_reads,self._postdtor_stores,self._postdtor_free_calls,
            self._postdtor_retention,
            dict(address=hex(self._postdtor_lookup_descriptor),before_hex=self._postdtor_lookup_before.hex(),after_hex=self._postdtor_lookup_before.hex(),verified_through='destructor_return'),
            [dict(index=i+1,PLT_offset=key[5:]) for i,key in enumerate(self._postdtor_trace) if key.startswith('main:0x347')],
            self._postdtor_next_call)
        for value,key in zip(values,PARENT_FIELDS):assert value==old[key],key
        self._idopen_old=old
        self._idopen_events=deepcopy(self._idopen_state['allocator_events_ref'])
        self._idopen_descriptor=self._reg(cpu,0);self._idopen_output=self._u(cpu,self._idopen_descriptor+8)
        self._idopen_prior=deepcopy(old['prior_objects_retention']['at_next'])
        self._idopen_ranges=[(int(x[key],16),width) for x in self._idopen_prior for key,width in (('object_address',24),('payload_address',8))]
        self._postdtor_active=False;self._postdtor_done=False;self._idopen_active=True
        self._idopen_track(cpu,pc);self._idopen_snapshot(cpu,pc,'VM_call')

    def _idopen_track(self,cpu,pc):
        self._idopen_count+=1;assert self._idopen_count<MAX_OBSERVATIONS
        if 0x51000000<=pc<0x51200000:domain,off='libc',pc-0x51000000
        else:
            assert self.image<=pc<self.image+0x400000
            domain,off='main',pc-self.image
        key=domain+':'+hex(off);self._idopen_trace.append(key);self._idopen_code[key]=bytes(cpu.mem_read(pc,4)).hex()

    def _idopen_snapshot(self,cpu,pc,kind):
        row=dict(kind=kind,index=self._idopen_count,pc=hex(pc-self.image),SP=hex(cpu.reg_read(arm.UC_ARM64_REG_SP)),
            registers={f'x{n}':hex(self._reg(cpu,n)) for n in (0,1,8,30)},
            descriptor_hex=bytes(cpu.mem_read(self._idopen_descriptor,48)).hex(),
            output_address=hex(self._idopen_output),output_hex=bytes(cpu.mem_read(self._idopen_output,16)).hex(),
            globals_3de700_hex=bytes(cpu.mem_read(self.image+0x3DE700,64)).hex(),
            prior_objects=[dict(object_address=x['object_address'],payload_address=x['payload_address'],
                object_hex=bytes(cpu.mem_read(int(x['object_address'],16),24)).hex(),payload_hex=bytes(cpu.mem_read(int(x['payload_address'],16),8)).hex()) for x in self._idopen_prior])
        for name,off,size in (('cache_mutex',0x3DE720,48),('cache_pair',0x3DE730,16)):
            pointer=self._u(cpu,self.image+off)
            if pointer and any(a<=pointer and pointer+size<=b for a,b,_ in cpu.mem_regions()):
                row[name]=dict(address=hex(pointer),hex=bytes(cpu.mem_read(pointer,size)).hex())
        if kind=='before_fopen_BL':
            row['call_instruction_hex']=bytes(cpu.mem_read(pc,4)).hex();row['file_inputs']={}
            for name,register,bound in (('path',0,64),('mode',1,16)):
                address=self._reg(cpu,register);raw=bytes(cpu.mem_read(address,bound)).split(b'\0',1)[0]
                assert len(raw)<bound
                row['file_inputs'][name]=dict(address=hex(address),length=len(raw),including_NUL_sha256=hashlib.sha256(raw+b'\0').hexdigest())
        if kind=='next_VM_call':
            d=self._reg(cpu,0);raw=bytes(cpu.mem_read(d,64));wrapper=self._reg(cpu,8)
            row.update(next_descriptor=hex(d),next_descriptor_hex=raw.hex(),next_wrapper=hex(wrapper-self.image),
                next_wrapper_hex=bytes(cpu.mem_read(wrapper,64)).hex(),VM_cursor=hex(self._u(cpu,self._reg(cpu,19))-self.image))
        self._idopen_rows.append(row)

    def native_runner(self,*args,**kwargs):
        old_write=kwargs['memory_write_observer']
        def write(cpu,address,size):
            if self._idopen_active:
                pc=cpu.reg_read(arm.UC_ARM64_REG_PC)
                if any(address<start+width and start<address+size for start,width in self._idopen_ranges):
                    self._idopen_protected.append(dict(index=self._idopen_count,PC=hex(pc),address=hex(address),size=size))
                    raise AssertionError('identifier path wrote a protected default string')
                if address<self._idopen_descriptor+48 and self._idopen_descriptor<address+size:
                    raise AssertionError('identifier getter wrote its callback descriptor')
                watched=((self._idopen_descriptor,48),(self._idopen_output,16),(self.image+0x3DE700,64))
                if any(address<start+width and start<address+size for start,width in watched):
                    self._idopen_writes.append(dict(index=self._idopen_count,native_pc=hex(pc-self.image),
                        address=hex(address),size=size,before_hex=bytes(cpu.mem_read(address,size)).hex()))
            if old_write:old_write(cpu,address,size)
        kwargs['memory_write_observer']=write
        return super().native_runner(*args,**kwargs)

    def observe(self,cpu,pc,state):
        self._idopen_state=state
        if not self._idopen_active:return super().observe(cpu,pc,state)
        self._idopen_track(cpu,pc);off=pc-self.image
        if off in (0x25BD8C,0x255CB4,0x255D84,0x255EC0,0x25BCE4,0x15F580,0x162620,0x1633B0,0x347F00,0x347F10,0x2886BC,previous.VM_RESUME):
            self._idopen_snapshot(cpu,pc,'return' if off==previous.VM_RESUME else 'path')
        if off==previous.VM_RESUME:self._idopen_returned=True
        if off==OPEN_CALL:
            self._idopen_snapshot(cpu,pc,'before_fopen_BL');self._idopen_done=True
        elif off==previous.VM_CALL:
            assert self._idopen_returned
            self._idopen_snapshot(cpu,pc,'next_VM_call');self._idopen_done=True
        if self._idopen_done:
            cpu.emu_stop();cpu.reg_write(arm.UC_ARM64_REG_PC,previous.oracle.STOP);return
        self._base_observe(cpu,pc,state)

    def finish(self,result,state,proof):
        assert self._idopen_done
        h=hashlib.sha256()
        for key in self._idopen_trace:h.update(key.encode()+bytes.fromhex(self._idopen_code[key]))
        ledgers=dict(allocator_counts=result['actual_allocator_counts'],inherited_service_counts=result['explicit_service_counts'],
            inherited_JNI_calls=proof['JNI_calls'],inherited_libc_SVC=proof['libc_SVC_boundaries'],inherited_main_SVC=proof['main_image_SVC_boundaries'],
            inherited_syscall_172=self._pid_syscalls,inherited_syscall_173=self._pp_syscalls,late_jni=self.late_jni_calls,java_dispatch=self.java_dispatch_calls)
        old=self._idopen_old
        assert self._idopen_events[len(self._postdtor_events_before):]==old['new_allocator_events']
        return dict(control=old['control'],retained_query_destructor=dict(case_result_sha256=digest(old),verified_fields=list(PARENT_FIELDS)),
            instruction_observations=self._idopen_count,instruction_trace_sha256=h.hexdigest(),observed_code_sha256=digest(self._idopen_code),
            snapshots=self._idopen_rows,native_writes=self._idopen_writes,protected_write_events=self._idopen_protected,
            observation_sites=self._idopen_trace,observed_code=self._idopen_code,
            new_allocator_events=result['allocator_events'][len(self._idopen_events):],callback_returned=self._idopen_returned,**ledgers,
            stop_boundary=dict(kind='before_identifier_seed_fopen_BL',stop_before=hex(OPEN_CALL),call_executed=False,PLT_executed=False,body_executed=False))


def run(path,libc):
    parent=prior_evidence();p=previous.bootstrap.module_prefix();p.digest.verify_images(path,libc)
    code=read_static(path,libc)
    def create(control):
        s=IdentifierSeedOpenScenario(control);s.path=path;s.continue_to_svc=True;return s
    rows=p.digest.context.replay(path,libc,case_controls=[p.CONTROL],_extension_factory=create,
        _request_profile=p.digest.previous.previous.name.previous.previous.PROFILE['name'],
        _handler_read_profile=p.digest.context.NULL_PAYLOAD_READ_PROFILE['name'])
    assert len(rows)==1
    components,negatives=independent_controls(path,libc)
    return dict(schema=SCHEMA,claims=claims_for(),providers=providers(),source_fingerprints=source_fingerprints(),
        input_provenance=provenance(parent),static_code=code,native_controls=components,component_rollback_checks=negatives,
        case_result=rows[0],case_result_sha256=digest(rows[0]))

def validate(data):
    parent=prior_evidence();old=parent['case_result']
    assert data['schema']==SCHEMA and data['claims']==claims_for() and data['providers']==providers()
    assert data['source_fingerprints']==source_fingerprints() and data['input_provenance']==provenance(parent)
    assert data['native_controls']==CONTROL_SPECS and data['component_rollback_checks']==ROLLBACK_SPECS
    assert len(CONTROL_SPECS)==44 and len(ROLLBACK_SPECS)==19
    assert set(data['static_code'])==set(CODE_SHA256)
    for domain,ranges in CODE_RANGES.items():
        for off,size in ranges:
            entry=data['static_code'][domain+':'+hex(off)];raw=bytes.fromhex(entry['hex'])
            assert len(raw)==entry['size']==size and raw_hash(raw)==entry['sha256']==CODE_SHA256[domain+':'+hex(off)]
    row=data['case_result'];assert data['case_result_sha256']==digest(row) and row['control']==old['control']
    assert row['retained_query_destructor']==dict(case_result_sha256=digest(old),verified_fields=list(PARENT_FIELDS))
    sites=row['observation_sites'];code=row['observed_code'];h=hashlib.sha256()
    assert len(sites)==row['instruction_observations']==EXPECTED['instruction_observations']<MAX_OBSERVATIONS
    assert set(sites)==set(code) and sites[0]=='main:'+hex(VM_CALL) and sites[-1]=='main:'+hex(OPEN_CALL)
    assert sites.count('main:'+hex(VM_CALL))==sites.count('main:'+hex(WRAPPER))==sites.count('main:'+hex(TARGET))==1
    for pc in (0x348460,0x348470,0x348480,VM_RESUME,0x2886BC):assert 'main:'+hex(pc) not in sites
    for key in sites:
        raw=bytes.fromhex(code[key]);assert len(raw)==4 and raw!=bytes.fromhex('010000d4')
        h.update(key.encode()+raw)
    assert h.hexdigest()==row['instruction_trace_sha256']==EXPECTED['instruction_trace_sha256']
    assert digest(code)==row['observed_code_sha256']==EXPECTED['observed_code_sha256']
    for domain,ranges in CODE_RANGES.items():
        for off,size in ranges:
            raw=data['static_code'][domain+':'+hex(off)]['hex']
            for pc in range(off,off+size,4):
                if domain+':'+hex(pc) in code:assert code[domain+':'+hex(pc)]==raw[(pc-off)*2:(pc-off+4)*2]
    assert row['snapshots']==EXPECTED['snapshots'] and row['native_writes']==EXPECTED['native_writes']
    assert row['protected_write_events']==[] and row['callback_returned'] is False
    before,stop=row['snapshots'][0],row['snapshots'][-1];base=row['control']['base']
    assert before['kind']=='VM_call' and before['descriptor_hex']==old['next_VM_call']['descriptor_hex']
    descriptor=old['next_VM_call']['descriptor_address'];output=old['next_VM_call']['static_expected_target_arguments']['x8']
    assert before['registers']['x0']==descriptor and before['output_address']==stop['output_address']==output
    entered=next(x for x in row['snapshots'] if x['pc']==hex(TARGET))
    assert entered['registers']['x0']==descriptor and entered['registers']['x8']==output
    assert stop['kind']=='before_fopen_BL' and stop['pc']==hex(OPEN_CALL) and stop['output_hex']=='00'*16
    assert all(x['descriptor_hex']==before['descriptor_hex'] for x in row['snapshots'])
    retained=old['prior_objects_retention']['at_next']
    assert all(x['prior_objects']==retained for x in row['snapshots'])
    state=bytes.fromhex(stop['globals_3de700_hex']);initial=bytes.fromhex(before['globals_3de700_hex'])
    assert len(state)==len(initial)==64 and initial[24:64]==bytes(40)
    assert int.from_bytes(state[40:48],'little')&1 and int.from_bytes(state[56:64],'little')&1
    assert not int.from_bytes(state[24:32],'little')&1
    mutex=stop['cache_mutex'];pair=stop['cache_pair'];raw=bytes.fromhex(mutex['hex'])
    assert int.from_bytes(state[32:40],'little')==int(mutex['address'],16)
    assert int.from_bytes(state[48:56],'little')==int(pair['address'],16) and pair['hex']=='00'*16
    assert len(raw)==48 and int.from_bytes(raw[:8],'little')==base+0x34C738 and int.from_bytes(raw[8:10],'little')==1
    assert stop['registers']['x0']==hex(base+0x3DE450) and stop['registers']['x1']==hex(base+0x3DE464)
    assert stop['call_instruction_hex']==code['main:'+hex(OPEN_CALL)]
    assert row['new_allocator_events']==EXPECTED['new_allocator_events'] and [x[1] for x in row['new_allocator_events']]==[48,16]
    counts=deepcopy(old['allocator_counts']);counts['malloc']+=2;assert row['allocator_counts']==counts
    for key,value in EXPECTED['ledgers'].items():assert row[key]==value,key
    assert row['stop_boundary']==dict(kind='before_identifier_seed_fopen_BL',stop_before=hex(OPEN_CALL),call_executed=False,PLT_executed=False,body_executed=False)

def damaged_evidence_rejected(data):
    changes=[(('claims','current_fopen_call_executed'),True),(('claims','current_identifier_callback_returned'),True),
        (('claims','current_identifier_published'),True),(('claims','current_outer_mutex_released'),True),
        (('claims','complete_standalone_signer_verified'),True),(('providers','new_providers'),['hidden']),
        (('source_fingerprints','owners','identifier_model'),'0'*64),
        (('case_result','retained_query_destructor','case_result_sha256'),'0'*64),
        (('case_result','instruction_observations'),0),(('case_result','instruction_trace_sha256'),'0'*64),
        (('case_result','observed_code_sha256'),'0'*64),(('case_result','observation_sites',0),'main:0x0'),
        (('case_result','callback_returned'),True),(('case_result','protected_write_events'),['hidden']),
        (('case_result','new_allocator_events'),[]),(('case_result','allocator_counts','malloc'),583),
        (('case_result','snapshots',0,'descriptor_hex'),'00'*48),
        (('case_result','snapshots',1,'registers','x8'),'0x0'),
        (('case_result','snapshots',-1,'kind'),'returned'),
        (('case_result','snapshots',-1,'output_hex'),'ff'*16),
        (('case_result','snapshots',-1,'cache_pair','hex'),'ff'*16),
        (('case_result','snapshots',-1,'cache_mutex','hex'),'00'*48),
        (('case_result','snapshots',-1,'globals_3de700_hex'),'00'*64),
        (('case_result','snapshots',-1,'prior_objects',0,'object_hex'),'00'*24),
        (('case_result','snapshots',-1,'file_inputs','path','including_NUL_sha256'),'0'*64),
        (('case_result','native_writes',0,'size'),1),(('case_result','stop_boundary','call_executed'),True),
        (('native_controls',0,'native_snapshot_input'),True),(('component_rollback_checks',0,'all_pages_unchanged'),False)]
    for key in EXPECTED['ledgers']:changes.append((('case_result',key),{}))
    for key in CODE_SHA256:changes.append((('static_code',key,'sha256'),'0'*64))
    for path,value in changes:
        bad=deepcopy(data);obj=bad
        for key in path[:-1]:obj=obj[key]
        obj[path[-1]]=value
        if path[0]=='case_result':bad['case_result_sha256']=digest(bad['case_result'])
        try:validate(bad)
        except (AssertionError,KeyError,ValueError,TypeError):continue
        raise AssertionError(f'damaged identifier seed-open evidence accepted: {path}')
    return len(changes)

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--elf',type=Path);parser.add_argument('--libc',type=Path)
    mode=parser.add_mutually_exclusive_group();mode.add_argument('--capture',action='store_true');mode.add_argument('--replay',action='store_true')
    args=parser.parse_args()
    if (args.capture or args.replay) and (not args.elf or not args.libc):parser.error('--capture and --replay require --elf and --libc')
    if args.capture:
        if EVIDENCE.exists():raise FileExistsError('frozen evidence already exists; refusing overwrite')
        data=run(args.elf,args.libc);validate(data);rejected=damaged_evidence_rejected(data)
        with EVIDENCE.open('x',encoding='utf-8',newline='\n') as output:output.write(json.dumps(data,indent=2)+'\n')
    else:
        data=json.loads(EVIDENCE.read_text(encoding='utf-8'));validate(data);rejected=damaged_evidence_rejected(data)
        if args.replay:assert run(args.elf,args.libc)==data,'fresh identifier seed-open replay differs'
    print(json.dumps(dict(schema=SCHEMA,damaged_evidence_rejected=rejected,native_controls=len(data['native_controls']),
        component_rollback_checks=len(data['component_rollback_checks']),instruction_observations=data['case_result']['instruction_observations'],
        current_fopen_call_executed=False,current_identifier_callback_returned=False,complete_standalone_signer_verified=False)))

if __name__=='__main__':main()
